/**
 * Regression corpus for the chat crisis classifier (AUDIT_CODE C2).
 * AUDITOR = messages quoted in AUDIT_CODE.md C2 (verbatim); the rest of the
 * auditor's 36 were not kept in the repo, so their categories are reconstructed
 * from the finding text. Everything else is written to sound like our members:
 * 55–85, typing on phones, typos, no punctuation, understatement.
 *
 * `cat` is the category the classifier must return. Recall must be 100%.
 */
import type { CrisisCategory } from "@/lib/db/types";

export interface CrisisCase {
  text: string;
  cat: CrisisCategory;
  src?: "auditor" | "verifier";
}

